# --- visits ---------------------------------------------------------------------------

def test_visit_request_confirm_cancel_reach_the_other_party(client):
    c, session = client
    owner_id, oh, buyer_id, bh, lid = _pair(c)
    c.post("/buyer/enquiries", json={"property_listing_id": lid}, headers=bh)
    r = c.post("/buyer/visits", json={"property_listing_id": lid, "scheduled_at": FUTURE(5),
                                       "note": "9876543210"}, headers=bh)
    assert r.status_code == 201, r.text
    vid = r.json()["id"]
    req = _rows(session, owner_id, "VISIT_REQUESTED")
    assert len(req) == 1 and req[0]["audience"] == "OWNER" and req[0]["category"] == "VISITS"
    assert req[0]["entity_type"] == "property_visit" and req[0]["entity_id"] == vid
    assert "IST" in req[0]["body"]
    _assert_clean(req[0])

    assert c.patch(f"/owner/visits/{vid}", json={"status": "CONFIRMED"}, headers=oh).status_code == 200
    assert c.patch(f"/owner/visits/{vid}", json={"status": "CONFIRMED"}, headers=oh).status_code == 200
    conf = _rows(session, buyer_id, "VISIT_CONFIRMED")
    assert len(conf) == 1 and conf[0]["audience"] == "BUYER"
    item = next(i for i in c.get("/notifications", headers=bh).json()["items"] if i["type"] == "VISIT_CONFIRMED")
    assert item["target"] == {"kind": "BUYER_VISIT", "id": vid}

    # Strict Phase 5: refused reschedule / note edits notify nobody.
    assert c.patch(f"/owner/visits/{vid}", json={"scheduled_at": FUTURE(6)}, headers=oh).status_code == 422
    assert c.patch(f"/buyer/visits/{vid}", json={"scheduled_at": FUTURE(8)}, headers=bh).status_code == 422
    assert c.patch(f"/buyer/visits/{vid}", json={"note": "Gate 2"}, headers=bh).status_code == 422
    assert _rows(session, buyer_id, "VISIT_RESCHEDULED") == []
    assert _rows(session, owner_id, "VISIT_RESCHEDULED") == []

    assert c.patch(f"/buyer/visits/{vid}", json={"status": "CANCELLED"}, headers=bh).status_code == 200
    assert len(_rows(session, owner_id, "VISIT_CANCELLED")) == 1
    item = next(i for i in c.get("/notifications", headers=oh).json()["items"] if i["type"] == "VISIT_CANCELLED")
    assert item["target"] == {"kind": "OWNER_VISIT", "id": vid}
    assert _rows(session, buyer_id, "VISIT_CANCELLED") == []  # actor

    assert sorted(r["type"] for r in _rows(session, owner_id)) == [
        "ENQUIRY_NEW", "VISIT_CANCELLED", "VISIT_REQUESTED"]
    assert sorted(r["type"] for r in _rows(session, buyer_id)) == ["VISIT_CONFIRMED"]


def test_owner_reject_notifies_buyer_and_buyer_cancel_notifies_owner(client):
    c, session = client
    owner_id, oh, buyer_id, bh, lid = _pair(c)
    c.post("/buyer/enquiries", json={"property_listing_id": lid}, headers=bh)
    vid = c.post("/buyer/visits", json={"property_listing_id": lid, "scheduled_at": FUTURE(5)},
                 headers=bh).json()["id"]
    # No counter-proposal under strict Phase 5: refused, nothing sent.
    assert c.patch(f"/owner/visits/{vid}", json={"scheduled_at": FUTURE(6)}, headers=oh).status_code == 422
    assert _rows(session, buyer_id) == []
    r = c.patch(f"/owner/visits/{vid}", json={"status": "REJECTED"}, headers=oh)
    assert r.status_code == 200 and r.json()["status"] == "REJECTED"
    rej = _rows(session, buyer_id, "VISIT_REJECTED")
    assert len(rej) == 1 and rej[0]["audience"] == "BUYER" and rej[0]["entity_id"] == vid
    _assert_clean(rej[0])
    assert _rows(session, owner_id, "VISIT_REJECTED") == []  # actor
    vid2 = c.post("/buyer/visits", json={"property_listing_id": lid, "scheduled_at": FUTURE(7)},
                  headers=bh).json()["id"]
    assert c.patch(f"/buyer/visits/{vid2}", json={"status": "CANCELLED"}, headers=bh).status_code == 200
    assert [x["entity_id"] for x in _rows(session, owner_id, "VISIT_CANCELLED")] == [vid2]


def test_owner_proposal_notifies_buyer_and_poster_confirmation_notifies_buyer(client):
    c, session = client
    owner_id, oh, buyer_id, bh, lid = _pair(c)
    c.post("/buyer/enquiries", json={"property_listing_id": lid}, headers=bh)
    r = c.post("/owner/visits", json={"property_listing_id": lid, "buyer_user_id": buyer_id,
                                       "scheduled_at": FUTURE(3)}, headers=oh)
    assert r.status_code == 201, r.text
    vid = r.json()["id"]
    assert [x["entity_id"] for x in _rows(session, buyer_id, "VISIT_PROPOSED")] == [vid]
    # Strict Phase 5: the buyer cannot confirm; the poster confirms its own
    # proposal and the buyer (the other party) is told.
    assert c.patch(f"/buyer/visits/{vid}", json={"status": "CONFIRMED"}, headers=bh).status_code == 422
    assert c.patch(f"/owner/visits/{vid}", json={"status": "CONFIRMED"}, headers=oh).status_code == 200
    conf = _rows(session, buyer_id, "VISIT_CONFIRMED")
    assert len(conf) == 1 and conf[0]["audience"] == "BUYER"
    assert _rows(session, owner_id, "VISIT_CONFIRMED") == []  # actor
    # Completion is not a notified event.
    assert c.patch(f"/owner/visits/{vid}", json={"status": "COMPLETED"}, headers=oh).status_code == 200
    assert sorted(r["type"] for r in _rows(session, buyer_id)) == ["VISIT_CONFIRMED", "VISIT_PROPOSED"]


def test_failed_visit_transition_creates_no_notification(client):
    c, session = client
    owner_id, oh, buyer_id, bh, lid = _pair(c)
    c.post("/buyer/enquiries", json={"property_listing_id": lid}, headers=bh)
    vid = c.post("/buyer/visits", json={"property_listing_id": lid, "scheduled_at": FUTURE(5)},
                 headers=bh).json()["id"]
    # Buyer may not confirm their own request (owner-only move): 422, nothing stored.
    assert c.patch(f"/buyer/visits/{vid}", json={"status": "CONFIRMED"}, headers=bh).status_code == 422
    assert _rows(session, owner_id, "VISIT_CONFIRMED") == []
    assert _rows(session, buyer_id) == []


