def test_owner_self_verify_and_self_reject_are_silent(client):
    c, session = client
    out, otoken = _owner(c)
    oh = auth_header(otoken)
    lid1 = _pending_listing(c, otoken)
    lid2 = _pending_listing(c, otoken)
    # Phase 2: self-verification is refused (admin-only) and changes nothing.
    r = c.post(f"/owner/listings/{lid1}/verify", headers=oh)
    assert r.status_code == 403 and r.json()["detail"]["code"] == "ADMIN_VERIFICATION_REQUIRED"
    assert session.execute(text("SELECT verification_status FROM property_listings WHERE id=:l"),
                           {"l": lid1}).scalar() == "PENDING"
    assert c.post(f"/owner/listings/{lid2}/reject", json={"reason": "x"}, headers=oh).status_code == 200
    assert _rows(session, out["user_id"]) == []


def test_admin_verify_and_reject_notify_owner_once(client):
    c, session = client
    out, otoken = _owner(c)
    owner_id = out["user_id"]
    ah, admin_id = _admin(c, session)
    lid1 = _pending_listing(c, otoken, "Garden Villa")
    lid2 = _pending_listing(c, otoken, "Lake House")
    for _ in range(2):  # second call is the idempotent same-state repeat
        assert c.post(f"/admin/listings/{lid1}/verify", headers=ah).status_code == 200
    assert c.post(f"/admin/listings/{lid2}/reject",
                  json={"reason": "Owner phone 9876543210 visible in photos", "category": "photos"},
                  headers=ah).status_code == 200
    verified = _rows(session, owner_id, "LISTING_VERIFIED")
    rejected = _rows(session, owner_id, "LISTING_REJECTED")
    assert len(verified) == 1 and len(rejected) == 1
    assert verified[0]["property_listing_id"] == lid1 and "Garden Villa" in verified[0]["body"]
    assert rejected[0]["property_listing_id"] == lid2 and "photos" not in rejected[0]["body"]
    _assert_clean(rejected[0])
    items = {i["type"]: i for i in c.get("/notifications", headers=auth_header(otoken)).json()["items"]}
    assert items["LISTING_REJECTED"]["target"] == {"kind": "OWNER_LISTING", "id": lid2}
    assert _rows(session, admin_id) == []


def test_automatic_verification_notifies_owner(client):
    c, session = client
    out, otoken = _owner(c)
    lid = _pending_listing(c, otoken, "Auto Flat")
    past = (datetime.now(timezone.utc) - timedelta(minutes=3)).replace(tzinfo=None)
    session.execute(text("UPDATE property_listings SET submitted_at=:t WHERE id=:i"), {"t": past, "i": lid})
    session.expire_all()
    from app.services import owner_listings as owner_svc
    assert owner_svc.transition_verification_automatic(session, lid) is not None
    assert owner_svc.transition_verification_automatic(session, lid) is None  # not pending any more
    session.flush()
    rows = _rows(session, out["user_id"])
    assert [r["type"] for r in rows] == ["LISTING_VERIFIED"]
    assert rows[0]["audience"] == "OWNER" and "Auto Flat" in rows[0]["body"]


# --- account --------------------------------------------------------------------------

def test_reactivation_notifies_user_and_suspension_is_silent(client):
    c, session = client
    ah, admin_id = _admin(c, session)
    buyer = _buyer(c)
    uid = buyer["user_id"]
    bh = auth_header(buyer["access_token"])
    assert c.post(f"/admin/users/{uid}/suspend", json={"reason": "spam"}, headers=ah).status_code == 200
    assert _rows(session, uid) == []
    assert c.get("/notifications", headers=bh).status_code == 403  # existing auth rule
    assert c.post(f"/admin/users/{uid}/reactivate", headers=ah).status_code == 200
    assert c.post(f"/admin/users/{uid}/reactivate", headers=ah).status_code == 200  # idempotent repeat
    rows = _rows(session, uid)
    assert [r["type"] for r in rows] == ["ACCOUNT_REACTIVATED"]
    assert (rows[0]["audience"], rows[0]["category"]) == ("ACCOUNT", "SYSTEM")
    assert "spam" not in rows[0]["body"]
    session.expire_all()
    api = c.get("/notifications", headers=bh).json()
    assert api["items"][0]["target"] == {"kind": "NONE", "id": None}
    assert _rows(session, admin_id) == []


# --- agents and buyer reschedules (review follow-up) -------------------------------------

def test_agent_enquiry_sender_receives_buyer_side_notifications(client):
    from tests.test_agent_buyer_activity import _agent

    c, session = client
    owner_id, oh, _buyer_id, _bh, lid = _pair(c)
    ah, agent_id = _agent(c, session, lid)  # BROKER with a trial area covering the listing
    assert c.post("/buyer/enquiries", json={"property_listing_id": lid, "message": "Client 9876543210"},
                  headers=ah).status_code == 201
    eid = _enquiry_id(session, agent_id, lid)
    new = _rows(session, owner_id, "ENQUIRY_NEW")
    assert len(new) == 1 and new[0]["entity_id"] == eid
    _assert_clean(new[0])

    assert c.post(f"/owner/leads/{eid}/messages", json={"message": "Sure"}, headers=oh).status_code == 201
    assert c.patch(f"/owner/leads/{eid}", json={"status": "CONTACTED"}, headers=oh).status_code == 200
    vid = c.post("/buyer/visits", json={"property_listing_id": lid, "scheduled_at": FUTURE(4)},
                 headers=ah).json()["id"]
    assert c.patch(f"/owner/visits/{vid}", json={"status": "CONFIRMED"}, headers=oh).status_code == 200

    agent_rows = _rows(session, agent_id)
    assert sorted(r["type"] for r in agent_rows) == ["ENQUIRY_REPLY", "LEAD_CONTACTED", "VISIT_CONFIRMED"]
    assert {r["audience"] for r in agent_rows} == {"BUYER"}  # buyer-side, whatever the sender's role
    assert sorted(r["type"] for r in _rows(session, owner_id)) == ["ENQUIRY_NEW", "VISIT_REQUESTED"]
    # The agent reads them in BROKER mode through the same user-scoped API.
    api = c.get("/notifications", params={"audience": "BUYER"}, headers=ah).json()
    assert api["total"] == 3 and api["unread_count"] == 3
    assert c.get("/users/me/role", headers=ah).json()["role"] == "BROKER"


def test_buyer_cannot_reschedule_a_pending_request_and_nobody_is_notified(client):
    """Strict Phase 5: the proposer cannot edit a submitted proposal."""
    c, session = client
    owner_id, oh, buyer_id, bh, lid = _pair(c)
    c.post("/buyer/enquiries", json={"property_listing_id": lid}, headers=bh)
    vid = c.post("/buyer/visits", json={"property_listing_id": lid, "scheduled_at": FUTURE(5)},
                 headers=bh).json()["id"]
    r = c.patch(f"/buyer/visits/{vid}", json={"scheduled_at": FUTURE(7)}, headers=bh)
    assert r.status_code == 422 and r.json()["detail"] == "The proposer cannot edit a submitted visit proposal"
    assert _rows(session, owner_id, "VISIT_RESCHEDULED") == []
    assert _rows(session, buyer_id) == []
